import { escape as e, button, requiredMarker, titleCase } from './ui.js';
export const body = (s) => `<div class="panel-body">${s}</div>`;
export const heading = (title, subtitle, actions = '') => `<div class="page-heading"><div><h1>${e(titleCase(title))}</h1><p>${e(subtitle)}</p></div><div class="page-actions">${actions}</div></div>`;
export const form = (command, id, version, fields, label = 'Save changes', extra = '') => `<form class="panel panel-body workflow-form" data-command="${e(command)}" data-resource="${e(id)}" ${version === undefined ? '' : `data-version="${version}"`} ${extra}><div class="form-error" role="alert"></div><div class="form-stack">${fields}</div><div class="form-actions"><span class="meta" data-save-status role="status"></span><button class="btn primary" type="submit">${e(label)}</button></div></form>`;
export const select = (name, label, options, selected = '', help = '') => { const optional = options.some(o => o.id === ''); return `<div class="field"><label for="field-${name}">${e(label)}${optional ? '' : ` ${requiredMarker()}`}</label><select id="field-${name}" name="${name}" ${optional ? '' : 'required'}>${options.map(o => `<option value="${e(o.id)}" ${selected === o.id ? 'selected' : ''}>${e(o.name)}</option>`).join('')}</select>${help ? `<small>${e(help)}</small>` : ''}</div>`; };
export const checks = (name, label, options, selected) => `<fieldset class="choice-group"><legend>${e(label)}</legend>${options.map(o => `<label class="check-label"><input type="checkbox" name="${e(name)}" value="${e(o.id)}" ${selected.includes(o.id) ? 'checked' : ''}><span>${e(o.name)}</span></label>`).join('')}</fieldset>`;
export const action = (text, type, id, payload = {}, confirm = '', version) => button(text, 'workflow-command', 'secondary', `data-command="${e(type)}" data-id="${e(id)}" data-payload="${e(JSON.stringify(payload))}" ${confirm ? `data-confirm="${e(confirm)}"` : ''} ${version === undefined ? '' : `data-version="${version}"`}`);
export const remove = (id, collection, itemId, version, dependencies) => action('Remove', 'scenario.remove', id, { collection, itemId }, `Remove this object? ${dependencies} Removal invalidates current validation.`, version);
export const hidden = (name, value) => `<input type="hidden" name="${e(name)}" value="${e(value)}">`;
